"""A dimensional-analysis quantity library (stdlib only).

A Quantity is a float value together with a 7-tuple of integer exponents
expressing its dimensions in the SI base quantities:

    (meter, kilogram, second, ampere, kelvin, mole, candela)
"""

from __future__ import annotations

import math
from typing import Tuple

__all__ = [
    "DimensionError",
    "Quantity",
    "m",
    "kg",
    "s",
    "A",
    "K",
    "mol",
    "cd",
    "N",
    "J",
    "W",
    "Pa",
    "mile",
    "hour",
    "hp",
]

# SI base exponents: (m, kg, s, A, K, mol, cd)
Exponents = Tuple[int, int, int, int, int, int, int]


class DimensionError(Exception):
    """Raised when quantities with incompatible dimensions are combined."""


def _zero() -> Exponents:
    return (0, 0, 0, 0, 0, 0, 0)


class Quantity:
    """A physical quantity: a float value and SI base exponents."""

    __slots__ = ("value", "exponents")

    def __init__(self, value: float, exponents: Exponents = _zero()) -> None:
        self.value = float(value)
        self.exponents = tuple(int(e) for e in exponents)  # type: ignore[assignment]
        if len(self.exponents) != 7:
            raise ValueError("exponents must be a 7-tuple")

    # -- helpers ---------------------------------------------------------

    def same_dimension(self, other: "Quantity") -> bool:
        """True if other has identical base-exponent dimensions."""
        if not isinstance(other, Quantity):
            return NotImplemented
        return self.exponents == other.exponents

    def _require_same_dimension(self, other: "Quantity", op: str) -> None:
        if not isinstance(other, Quantity):
            raise TypeError(f"cannot apply {op!r} between Quantity and {type(other).__name__}")
        if self.exponents != other.exponents:
            raise DimensionError(
                f"incompatible dimensions for {op!r}: "
                f"{_format_dims(self.exponents)} vs {_format_dims(other.exponents)}"
            )

    def _dimensionless(self) -> bool:
        return self.exponents == _zero()

    # -- arithmetic -------------------------------------------------------

    def __add__(self, other: "Quantity") -> "Quantity":
        self._require_same_dimension(other, "+")
        assert isinstance(other, Quantity)  # for type checkers
        return Quantity(self.value + other.value, self.exponents)

    __radd__ = __add__

    def __sub__(self, other: "Quantity") -> "Quantity":
        self._require_same_dimension(other, "-")
        assert isinstance(other, Quantity)  # for type checkers
        return Quantity(self.value - other.value, self.exponents)

    def __rsub__(self, other: "Quantity") -> "Quantity":
        # only reached when other is a Quantity (else TypeError above path)
        assert isinstance(other, Quantity)
        other._require_same_dimension(self, "-")
        return Quantity(other.value - self.value, other.exponents)

    def __mul__(self, other) -> "Quantity":
        if isinstance(other, Quantity):
            return Quantity(
                self.value * other.value,
                tuple(a + b for a, b in zip(self.exponents, other.exponents)),
            )
        if isinstance(other, (int, float)):
            return Quantity(self.value * other, self.exponents)
        return NotImplemented

    __rmul__ = __mul__

    def __truediv__(self, other) -> "Quantity":
        if isinstance(other, Quantity):
            return Quantity(
                self.value / other.value,
                tuple(a - b for a, b in zip(self.exponents, other.exponents)),
            )
        if isinstance(other, (int, float)):
            return Quantity(self.value / other, self.exponents)
        return NotImplemented

    def __rtruediv__(self, other) -> "Quantity":
        if isinstance(other, (int, float)):
            return Quantity(other / self.value, tuple(-e for e in self.exponents))
        return NotImplemented

    def __neg__(self) -> "Quantity":
        return Quantity(-self.value, self.exponents)

    def __pos__(self) -> "Quantity":
        return Quantity(self.value, self.exponents)

    def __abs__(self) -> "Quantity":
        return Quantity(abs(self.value), self.exponents)

    # -- powers -----------------------------------------------------------

    def __pow__(self, n: int) -> "Quantity":
        if not isinstance(n, int):
            raise TypeError("exponent must be an integer")
        return Quantity(
            self.value ** n,
            tuple(n * e for e in self.exponents),
        )

    def sqrt(self) -> "Quantity":
        """Square root; requires all base exponents to be even."""
        odd = [name for name, e in zip(_DIM_NAMES, self.exponents) if e % 2 != 0]
        if odd:
            raise DimensionError(
                f"sqrt requires even exponents, odd in: {', '.join(odd)}"
            )
        half = tuple(e // 2 for e in self.exponents)
        return Quantity(math.sqrt(self.value), half)

    # -- comparisons (like dimensions only) --------------------------------

    def _compare(self, other, op_name: str) -> bool:
        if isinstance(other, (int, float)):
            if not self._dimensionless():
                raise DimensionError(
                    f"cannot compare {_format_dims(self.exponents)} to a bare number"
                )
            return getattr(self.value, op_name)(other)
        self._require_same_dimension(other, op_name)
        assert isinstance(other, Quantity)
        return getattr(self.value, op_name)(other.value)

    def __eq__(self, other):
        if isinstance(other, (int, float)) and self._dimensionless():
            return self.value == other
        try:
            return self._compare(other, "__eq__")
        except TypeError:
            return NotImplemented

    def __lt__(self, other):
        return self._compare(other, "__lt__")

    def __le__(self, other):
        return self._compare(other, "__le__")

    def __gt__(self, other):
        return self._compare(other, "__gt__")

    def __ge__(self, other):
        return self._compare(other, "__ge__")

    def __hash__(self):
        # hashable only meaningfully when dimensionless; keep general anyway
        return hash((self.value, self.exponents))

    # -- repr --------------------------------------------------------------

    def __repr__(self) -> str:
        dims = _format_dims(self.exponents)
        if dims == "1":
            return f"Quantity({self.value})"
        return f"Quantity({self.value}, {dims})"


_DIM_NAMES = ("m", "kg", "s", "A", "K", "mol", "cd")


def _format_dims(exponents: Exponents) -> str:
    parts = []
    for name, e in zip(_DIM_NAMES, exponents):
        if e == 0:
            continue
        if e == 1:
            parts.append(name)
        else:
            parts.append(f"{name}^{e}")
    return "*".join(parts) if parts else "1"


# ---------------------------------------------------------------------------
# Named units (SI base units)
# ---------------------------------------------------------------------------

m = Quantity(1.0, (1, 0, 0, 0, 0, 0, 0))       # meter
kg = Quantity(1.0, (0, 1, 0, 0, 0, 0, 0))      # kilogram
s = Quantity(1.0, (0, 0, 1, 0, 0, 0, 0))       # second
A = Quantity(1.0, (0, 0, 0, 1, 0, 0, 0))       # ampere
K = Quantity(1.0, (0, 0, 0, 0, 1, 0, 0))       # kelvin
mol = Quantity(1.0, (0, 0, 0, 0, 0, 1, 0))     # mole
cd = Quantity(1.0, (0, 0, 0, 0, 0, 0, 1))      # candela

# Derived units
N = kg * m / s ** 2                            # newton
J = N * m                                      # joule
W = J / s                                      # watt
Pa = N / m ** 2                                # pascal

# Non-SI units
mile = Quantity(1609.344, m.exponents)         # statute mile in meters
hour = Quantity(3600.0, s.exponents)           # hour in seconds
hp = Quantity(745.6998715822702, W.exponents)  # mechanical horsepower in watts

